function formationFilename(value){const date=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date());const slug=(value.name||'untitled').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)||'untitled';return 'milkroad-formation-'+value.gameMode+'-'+value.mode+'-'+slug+'-'+date+'.json'}
async function persistAccount(publish){save();if(!draft.name.trim()){status('Give your formation a name before saving or publishing.');$('draft-name').focus();return}if(publish&&!await confirmDialog('Publish this formation to the public formation list? Your private saved copy will remain in your account.'))return;const buttons=[$('account-save'),$('account-publish')];buttons.forEach(b=>b.disabled=true);try{const payload=cleanDraft(draft,known),result=await saveAccountFormation({id:recordId,revision:recordRevision,name:draft.name,payload,publish});recordId=result.id;recordRevision=result.revision;const url=new URL(location.href);url.searchParams.set('formation',recordId);url.searchParams.set('private','1');url.hash='';history.replaceState(null,'',url);status(publish?'Published to the formation list and saved in your account.':'Private changes saved. Any published snapshot is unchanged until you publish again.');return true}catch(error){status(error.message)}finally{buttons.forEach(b=>b.disabled=false)}}
