function renderZoboField(){for(const z of draft.zobos||[]){const entry=zoboEntries.find(e=>e.id===z.id),b=z.zone==='green'?$('board').children[z.index]:$('enemy-field').children[z.index];if(!entry||!b||z.zone==='green'&&draft.cells[z.index])continue;b.replaceChildren(img(entry.icon,entry.name));b.classList.add('zobo-cell');b.classList.toggle('boss-zobo',!!entry.boss);b.draggable=false;b.ondragstart=event=>event.dataTransfer.setData('text/plain',JSON.stringify({zobo:z}));installZoboTouch(b,z);b.setAttribute('aria-label',entry.name+' — tap to remove');b.onclick=()=>{if(zoboCandidate)placeZobo(z.zone,z.index);else if(candidate){status('Move or remove the Zobo before placing a Tatari here.')}else{draft.zobos=draft.zobos.filter(v=>v!==z);renderBoard();save()}}}}
document.querySelectorAll('[data-picker-tab]').forEach(button=>button.onclick=()=>{pickerTab=button.dataset.pickerTab;candidate=null;zoboCandidate=null;$('search').value='';if(pickerTab==='zobo'){$('full-field').checked=true;draft.fullField=true;renderBoard()}renderPicker();renderCandidate()});

function moveZobo(source,zone,index){if(zone==='green'&&draft.cells[index]){status('Move the Tatari first.');return}const unit=(draft.zobos||[]).find(z=>z.zone===source.zone&&z.index===source.index);if(!unit)return;const other=draft.zobos.find(z=>z.zone===zone&&z.index===index);if(other&&other!==unit){other.zone=source.zone;other.index=source.index}unit.zone=zone;unit.index=index;renderBoard();save()}
function installZoboTouch(button,zobo){let gesture=null;const clean=()=>{gesture?.ghost?.remove();button.classList.remove('touch-moving');gesture=null};button.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY};button.setPointerCapture(e.pointerId)});button.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.id)return;if(!gesture.ghost&&Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)<8)return;e.preventDefault();if(!gesture.ghost){gesture.ghost=button.querySelector('img:not(.tiny-element)').cloneNode();gesture.ghost.className='touch-drag-art';document.body.append(gesture.ghost);button.classList.add('touch-moving')}gesture.ghost.style.left=e.clientX+'px';gesture.ghost.style.top=e.clientY+'px'});button.addEventListener('pointerup',e=>{if(!gesture)return;const moved=!!gesture.ghost,target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.board-cell,.enemy-cell');clean();if(moved){e.preventDefault();const block=e=>{e.preventDefault();e.stopImmediatePropagation()};button.addEventListener('click',block,{capture:true,once:true});setTimeout(()=>button.removeEventListener('click',block,true),400);if(target)moveZobo(zobo,target.hasAttribute('data-cell')?'green':'grey',Number(target.dataset.cell??target.dataset.enemyCell))}});button.addEventListener('pointercancel',clean);button.addEventListener('lostpointercapture',clean)}

$('close-effect').onclick=()=>$('effect-dialog').close();
$('effect-dialog').addEventListener('click',event=>{if(event.target===$('effect-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close()}});

