function withoutAura(text){return String(text).split(/(?<=[.!?])\s+/).filter(sentence=>! /\bAura\s*:/i.test(sentence)).join(' ').trim()}

function closeDrafterDropdowns(target){for(const menu of document.querySelectorAll('.draft-more[open],.formation-advanced[open]'))if(!target||!menu.contains(target))menu.open=false;for(const field of document.querySelectorAll('.boss-picker'))if(!target||!field.contains(target)){const list=field.querySelector('.boss-options');if(list)list.hidden=true;field.querySelector('.boss-select')?.setAttribute('aria-expanded','false')}}
document.addEventListener('click',event=>closeDrafterDropdowns(event.target));
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeDrafterDropdowns()});

$('formation-notes').oninput=()=>{draft.shareNotes=$('formation-notes').value;save()};

function clearRanges(){rangeSubject=null;document.querySelectorAll('.range-attack,.range-skill').forEach(tile=>tile.classList.remove('range-attack','range-skill'))}
function previewRanges(index,unit){clearRanges();if(!unit||zoboCandidate||document.querySelector('.chip-hover-target'))return;rangeSubject={index,...unit};paintRanges()}
function paintRanges(){
 const help=$('range-help');if(!help)return;
 const enabled=rangeOptions.attack,profile=rangeProfile(draft.gameMode);
 help.hidden=!enabled;
 help.textContent=!profile?'Range previews are not available for this mode yet.':!rangeData?'Range data unavailable. Placement still works.':'Yellow tiles show the standard attack range. Skill effects that change range may not appear in this preview.';
 if(!enabled||!profile||!rangeData||!rangeSubject)return;
 const size=boards[draft.gameMode],enemyRows=$('enemy-field').hidden?0:size.rows;
 const tiles=rangeTiles(rangeData,{...rangeSubject,mode:draft.gameMode,...size,enemyRows});
 const mark=(selector,offset)=>document.querySelectorAll(selector).forEach(tile=>{const i=Number(tile.dataset.cell??tile.dataset.enemyCell)+offset;tile.classList.toggle('range-attack',rangeOptions.attack&&tiles.attack.has(i));tile.classList.remove('range-skill')});
 mark('#board .board-cell',enemyRows*size.cols);if(enemyRows)mark('#enemy-field .enemy-cell',0);
}
for(const [id,key] of [['attack-range','attack'],['skill-range','skill']]){const checkbox=$(id);checkbox.checked=!!rangeOptions[key];checkbox.onchange=()=>{rangeOptions[key]=key==='attack'&&checkbox.checked;try{localStorage.setItem('milkroad-range-options',JSON.stringify(rangeOptions))}catch{}const subject=rangeSubject;clearRanges();rangeSubject=subject;paintRanges()}}
$('board').addEventListener('pointerleave',()=>{if(!rangeDragging)clearRanges()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){rangeDragging=false;clearRanges()}});

function openMobilePicker(target=null,tab='tatari'){
 if(!mobilePickerMedia.matches||!mobilePickerDialog)return;mobilePickerTarget=target;candidate=null;zoboCandidate=null;pickerTab=tab;$('search').value='';
 const cols=boards[draft.gameMode].cols;$('mobile-picker-title').textContent=target?'Picker · Row '+(Math.floor(target.index/cols)+1)+', Column '+(target.index%cols+1):'Formation picker';$('mobile-picker-feedback').textContent=target?'Choose a '+(target.zone==='grey'?'Zobo':'Tatari or Zobo')+' for this tile.':'Choose a Tatari or Zobo, then tap a tile. Chips can be selected here too.';
 renderPicker();renderCandidate();mobilePickerDialog.showModal();document.body.classList.add('mobile-picker-open');
}
