 const panel=$('tatari-section'),anchor=document.createComment('Desktop picker position');panel.before(anchor);const dialog=el('dialog',undefined,'mobile-picker-dialog');dialog.id='mobile-picker-dialog';dialog.setAttribute('aria-labelledby','mobile-picker-title');const header=el('div',undefined,'modal-head mobile-picker-head'),heading=el('h3','Formation picker'),close=el('button','×','mobile-picker-close'),feedback=el('p',undefined,'caption mobile-picker-feedback');heading.id='mobile-picker-title';feedback.id='mobile-picker-feedback';feedback.setAttribute('role','status');close.type='button';close.setAttribute('aria-label','Close picker');header.append(heading,close);dialog.append(header,feedback);document.body.append(dialog);mobilePickerDialog=dialog;
 const cancel=()=>{candidate=null;zoboCandidate=null;renderCandidate();dialog.close()};close.onclick=cancel;dialog.addEventListener('cancel',()=>{candidate=null;zoboCandidate=null;renderCandidate()});dialog.addEventListener('close',()=>{document.body.classList.remove('mobile-picker-open');const target=mobilePickerTarget;mobilePickerTarget=null;if(target){const tile=document.querySelector(target.zone==='green'?'#board [data-cell="'+target.index+'"]':'#enemy-field [data-enemy-cell="'+target.index+'"]');tile?.focus({preventScroll:true})}});
 const sync=()=>{$('placement-hint').textContent=mobilePickerMedia.matches?'Tap an empty tile to choose a Tatari. Tap a fielded Tatari to edit it.':'Choose a Tatari, then tap a cell.';if(mobilePickerMedia.matches){dialog.append(panel)}else{if(dialog.open)dialog.close();anchor.after(panel);document.body.classList.remove('mobile-picker-open')}};mobilePickerMedia.addEventListener('change',sync);sync();
 const nav=document.querySelector('a[href$="#tatari-section"]');if(nav){nav.textContent='Picker';nav.addEventListener('click',event=>{if(mobilePickerMedia.matches){event.preventDefault();openMobilePicker()}})}
 const replace=el('button','Replace Tatari','btn secondary mobile-replace-tatari');replace.type='button';replace.onclick=()=>{const index=editing;pickPlayer=draft.mode==='duo'?owner(index,draft.mode,draft.cells[index]):1;$('unit-dialog').close();openMobilePicker({zone:'green',index})};$('unit-dialog').querySelector('.modal-actions').prepend(replace);
